-- ============================================================
-- Ocean Music — Conteúdo de Piano: Evoluindo e Teoria: Harmonia e
-- Escalas (Etapa 17.2). Arquivo gerado a partir do conteúdo revisado.
--
-- Cadastra etapas, lições e exercícios das 2 trilhas (as primeiras
-- recomendações do perfil do Bruno). Pode ser executado mais de uma
-- vez: cada item é identificado por slug/key e, se já existir, é
-- ATUALIZADO (útil depois de ajustar algum texto).
--
-- Ordem para recriar o banco do zero:
--   schema.sql -> seed.sql -> add-audio-content.sql -> este arquivo
--
-- Executar SEMPRE com UTF-8 (ver docs/estado-do-projeto.md):
--   $env:PGCLIENTENCODING = "UTF8"; chcp 65001
-- ============================================================
\set ON_ERROR_STOP on

BEGIN;

-- Etapas
INSERT INTO stages (track_id, slug, title, position)
SELECT t.id, v.slug, v.title, v.position
FROM (VALUES
  ('piano-evoluindo', 'escalas-e-acordes', 'Escalas e acordes', 1),
  ('piano-evoluindo', 'leitura-e-expressao', 'Leitura e expressão', 2),
  ('piano-evoluindo', 'repertorio', 'Repertório', 3),
  ('teoria-harmonia-escalas', 'tonalidades', 'Tonalidades', 1),
  ('teoria-harmonia-escalas', 'intervalos-e-campo-harmonico', 'Intervalos e campo harmônico', 2),
  ('teoria-harmonia-escalas', 'cadencias', 'Cadências', 3)
) AS v(track_slug, slug, title, position)
JOIN tracks t ON t.slug = v.track_slug
ON CONFLICT (track_id, slug) DO UPDATE SET title = EXCLUDED.title;

-- Lições (o conteúdo é uma lista de blocos: text, tip, audio_demo, practice)
INSERT INTO lessons (stage_id, slug, title, position, content)
SELECT s.id, v.slug, v.title, v.position, v.content::jsonb
FROM (VALUES
  ('piano-evoluindo', 'escalas-e-acordes', 'escalas-maiores-menores', 'Escalas maiores e menores', 1, '[{"type":"text","title":"Escala maior: a fórmula","body":"Toda escala maior segue a mesma sequência de tons (T) e semitons (S): T – T – S – T – T – T – S. Em Dó maior, isso dá Dó, Ré, Mi, Fá, Sol, Lá, Si, usando só as teclas brancas."},{"type":"text","title":"Escala menor natural","body":"A escala menor natural segue outra fórmula: T – S – T – T – S – T – T. Lá menor natural usa só teclas brancas: Lá, Si, Dó, Ré, Mi, Fá, Sol. Lá menor é a relativa menor de Dó maior: as duas usam as mesmas notas."},{"type":"audio_demo","caption":"Ouça a nota Dó, ponto de partida da escala de Dó maior.","stimulus":{"kind":"note","note":"C4"}}]'),
  ('piano-evoluindo', 'escalas-e-acordes', 'acordes-e-inversoes', 'Acordes e inversões', 2, '[{"type":"text","title":"Tríades maiores e menores","body":"Uma tríade tem três notas: fundamental, terça e quinta. Na tríade maior, a terça fica 4 semitons acima da fundamental; na menor, 3 semitons. Dó maior: Dó – Mi – Sol. Dó menor: Dó – Mi♭ – Sol."},{"type":"text","title":"Inversões","body":"Inverter um acorde é mudar a nota mais grave. Dó – Mi – Sol está em posição fundamental. Mi – Sol – Dó é a 1ª inversão (terça no baixo). Sol – Dó – Mi é a 2ª inversão (quinta no baixo). As notas são as mesmas; só a ordem muda."},{"type":"audio_demo","caption":"Ouça o acorde de Dó maior.","stimulus":{"kind":"chord","notes":["C4","E4","G4"]}},{"type":"audio_demo","caption":"Agora ouça o acorde de Dó menor. Compare: o som costuma parecer mais sombrio.","stimulus":{"kind":"chord","notes":["C4","Eb4","G4"]}}]'),
  ('piano-evoluindo', 'leitura-e-expressao', 'leitura-de-partitura', 'Leitura de partitura', 1, '[{"type":"text","title":"Pauta e claves","body":"A pauta tem 5 linhas e 4 espaços. A clave indica o nome das notas: no piano, a mão direita costuma ler na clave de Sol e a esquerda, na clave de Fá."},{"type":"text","title":"Clave de Sol: linhas e espaços","body":"Na clave de Sol, as linhas, de baixo para cima, são Mi, Sol, Si, Ré, Fá. Os espaços, de baixo para cima, são Fá, Lá, Dó, Mi."},{"type":"tip","body":"Memorize primeiro só as linhas, depois só os espaços, e por fim junte tudo."},{"type":"practice","instruction":"Em um papel, desenhe uma pauta e escreva as notas Mi, Sol, Si, Ré e Fá nas cinco linhas, de baixo para cima. Depois confira com o texto acima."}]'),
  ('piano-evoluindo', 'leitura-e-expressao', 'dinamica-e-articulacao', 'Dinâmica e articulação', 2, '[{"type":"text","title":"Dinâmica","body":"Dinâmica é a variação de volume. Da mais fraca para a mais forte: pp (pianíssimo), p (piano), mp (meio piano), mf (meio forte), f (forte) e ff (fortíssimo)."},{"type":"text","title":"Articulação","body":"Articulação é a forma de atacar cada nota. Staccato: notas curtas e destacadas, marcadas com um ponto. Legato: notas ligadas, sem pausa entre elas, marcadas com uma linha curva (ligadura)."},{"type":"tip","body":"O nome do instrumento vem de pianoforte: ao contrário do cravo, ele permitia tocar fraco (piano) ou forte (forte) na mesma tecla, só variando a força do toque."},{"type":"practice","instruction":"Toque a mesma nota quatro vezes, com o metrônomo: primeiro em p, depois mf, depois f e, por fim, volte para p. Ouça o volume mudar só pela força do toque.","metronomeBpm":60}]'),
  ('piano-evoluindo', 'repertorio', 'pecas-classicas', 'Peças clássicas de iniciação', 1, '[{"type":"text","title":"Por onde começar","body":"Muitos pianistas começam com peças curtas, como o Prelúdio em Dó maior de Bach, a Sonata Fácil em Dó maior de Mozart, Für Elise (Para Elisa), de Beethoven, e peças do Álbum para a Juventude, de Schumann. Elas treinam leitura, pulso e expressão."},{"type":"text","title":"Como estudar uma peça","body":"Divida a peça em frases curtas. Estude cada mão separada, devagar, e só depois junte as duas. Aumente o andamento aos poucos, sem perder a regularidade."},{"type":"practice","instruction":"Escolha uma frase de 2 a 4 compassos da sua peça e toque, mãos separadas, com o metrônomo em 60 BPM. Só aumente 5 BPM quando conseguir tocar três vezes seguidas sem erro.","metronomeBpm":60}]'),
  ('piano-evoluindo', 'repertorio', 'subir-ao-palco', 'Subir ao palco', 2, '[{"type":"text","title":"Nervosismo é normal","body":"Sentir frio na barriga antes de tocar é comum, até entre profissionais. O que ajuda não é eliminar o nervosismo, mas se preparar: conhecer bem a peça e ensaiar nas condições da apresentação."},{"type":"text","title":"Antes de se apresentar","body":"Toque a peça de ponta a ponta, sem parar, para alguém ou gravando em vídeo. Se errar, continue: na apresentação não dá para voltar. Antes de começar, respire fundo e relaxe os ombros e os braços."},{"type":"tip","body":"A plateia costuma perceber menos erros do que o músico imagina. Seguir em frente é melhor do que parar."},{"type":"practice","instruction":"Toque sua peça de ponta a ponta três vezes seguidas, sem parar para corrigir erros, com o metrônomo em um andamento confortável.","metronomeBpm":70}]'),
  ('teoria-harmonia-escalas', 'tonalidades', 'tonalidades-e-armaduras', 'Tonalidades e armaduras', 1, '[{"type":"text","title":"O que é uma tonalidade","body":"Tonalidade é o conjunto de notas e o centro (a tônica) em torno do qual uma música se organiza. Uma música em Sol maior usa as notas da escala de Sol maior, e Sol é a nota de repouso."},{"type":"text","title":"Armadura de clave","body":"A armadura é o grupo de sustenidos (#) ou bemóis (♭) escrito no início da pauta, logo depois da clave. Ela indica a tonalidade. Dó maior não tem alterações; Sol maior tem 1 sustenido (Fá#); Fá maior tem 1 bemol (Si♭)."},{"type":"text","title":"Ordem dos sustenidos","body":"Os sustenidos aparecem sempre na mesma ordem: Fá, Dó, Sol, Ré, Lá, Mi, Si. Cada tonalidade com sustenidos está uma quinta acima da anterior: Dó (nenhum), Sol (1), Ré (2), Lá (3), Mi (4)."},{"type":"audio_demo","caption":"Ouça o acorde de Sol maior, o acorde de repouso da tonalidade de Sol maior.","stimulus":{"kind":"chord","notes":["G3","B3","D4"]}}]'),
  ('teoria-harmonia-escalas', 'tonalidades', 'escalas-menores', 'Escalas menores', 2, '[{"type":"text","title":"Três formas da escala menor","body":"A escala menor tem três formas: natural, harmônica e melódica. A natural usa as mesmas notas da relativa maior. As outras duas alteram notas para criar mais tensão em direção à tônica."},{"type":"text","title":"Menor harmônica","body":"A menor harmônica é a natural com o 7º grau elevado em um semitom. Em Lá menor: Lá, Si, Dó, Ré, Mi, Fá, Sol#. O salto de Fá para Sol# (um tom e meio) é a marca do seu som."},{"type":"text","title":"Menor melódica","body":"Na menor melódica, subindo, o 6º e o 7º graus são elevados. Em Lá menor: Lá, Si, Dó, Ré, Mi, Fá#, Sol#. Ao descer, ela costuma voltar à forma natural."},{"type":"audio_demo","caption":"Ouça o acorde de Lá menor, tônica destas escalas.","stimulus":{"kind":"chord","notes":["A3","C4","E4"]}}]'),
  ('teoria-harmonia-escalas', 'intervalos-e-campo-harmonico', 'intervalos-e-inversoes', 'Intervalos e inversões', 1, '[{"type":"text","title":"Intervalo","body":"Intervalo é a distância entre duas notas. O nome tem um número, contado pelas notas da escala incluindo as duas pontas, e uma qualidade (justo, maior, menor, aumentado ou diminuto). De Dó a Sol há 5 notas (Dó, Ré, Mi, Fá, Sol): é uma 5ª justa."},{"type":"text","title":"Inversão de intervalos","body":"Inverter um intervalo é levar a nota mais grave uma oitava acima. O número do intervalo e o do invertido somam 9: uma 3ª vira 6ª, e uma 5ª vira 4ª. Maior vira menor (e vice-versa), aumentado vira diminuto, e o justo continua justo."},{"type":"audio_demo","caption":"Ouça uma 3ª maior: Dó e Mi tocadas juntas.","stimulus":{"kind":"chord","notes":["C4","E4"]}},{"type":"audio_demo","caption":"Agora uma 3ª menor: Dó e Mi♭. Perceba a diferença.","stimulus":{"kind":"chord","notes":["C4","Eb4"]}}]'),
  ('teoria-harmonia-escalas', 'intervalos-e-campo-harmonico', 'campo-harmonico', 'Campo harmônico', 2, '[{"type":"text","title":"O que é o campo harmônico","body":"Campo harmônico é o conjunto de acordes formados sobre cada nota de uma escala, usando só as notas da própria escala. Em uma escala maior, são sete acordes, um para cada grau."},{"type":"text","title":"Campo harmônico de Dó maior","body":"Os acordes são: C (I), Dm (ii), Em (iii), F (IV), G (V), Am (vi) e Bdim (vii°). Os graus I, IV e V são maiores; ii, iii e vi são menores; e o vii° é diminuto."},{"type":"tip","body":"I, IV e V são os acordes principais: tônica, subdominante e dominante. Com só esses três já dá para acompanhar muitas músicas."},{"type":"audio_demo","caption":"Acorde I (Dó maior): passa a sensação de repouso.","stimulus":{"kind":"chord","notes":["C4","E4","G4"]}},{"type":"audio_demo","caption":"Acorde V (Sol maior): cria tensão e pede para voltar ao I.","stimulus":{"kind":"chord","notes":["G3","B3","D4"]}}]'),
  ('teoria-harmonia-escalas', 'cadencias', 'cadencias', 'Cadências', 1, '[{"type":"text","title":"O que é uma cadência","body":"Cadência é a sequência de acordes que encerra uma frase musical, como uma pontuação: pode dar sensação de pausa, de conclusão ou de suspense."},{"type":"text","title":"Autêntica e plagal","body":"Cadência autêntica: V → I (G → C, em Dó maior). É a mais conclusiva, como um ponto final. Cadência plagal: IV → I (F → C), conhecida como o ''amém'' dos hinos."},{"type":"text","title":"Semicadência e de engano","body":"Semicadência: termina no V e deixa a frase em suspenso, como uma vírgula. Cadência de engano: V → vi (G → Am). Esperávamos o I, mas a música surpreende indo para o vi."},{"type":"audio_demo","caption":"Passo 1: ouça o acorde de Sol maior (V).","stimulus":{"kind":"chord","notes":["G3","B3","D4"]}},{"type":"audio_demo","caption":"Passo 2: agora ouça o acorde de Dó maior (I). Em sequência, os dois formam a cadência autêntica.","stimulus":{"kind":"chord","notes":["C4","E4","G4"]}},{"type":"practice","instruction":"Se tiver um teclado ou um violão por perto, toque G e depois C. Sinta a sensação de chegada ao tocar o C."}]')
) AS v(track_slug, stage_slug, slug, title, position, content)
JOIN tracks t ON t.slug = v.track_slug
JOIN stages s ON s.track_id = t.id AND s.slug = v.stage_slug
ON CONFLICT (stage_id, slug) DO UPDATE SET title = EXCLUDED.title, content = EXCLUDED.content;

-- Exercícios (multiple_choice, true_false e audio_choice)
INSERT INTO exercises (lesson_id, key, position, type, prompt, payload, solution, explanation)
SELECT l.id, v.key, v.position, v.type, v.prompt, v.payload::jsonb, v.solution::jsonb, v.explanation
FROM (VALUES
  ('piano-evoluindo', 'escalas-maiores-menores', 'ex-1', 1, 'multiple_choice', 'Qual é a fórmula de tons (T) e semitons (S) da escala maior?', '{"options":[{"id":"a","text":"T – T – S – T – T – T – S"},{"id":"b","text":"T – S – T – T – S – T – T"},{"id":"c","text":"S – T – T – S – T – T – T"}]}', '{"correctOptionId":"a"}', 'A escala maior é T – T – S – T – T – T – S. A segunda opção é a fórmula da escala menor natural.'),
  ('piano-evoluindo', 'escalas-maiores-menores', 'ex-2', 2, 'true_false', 'Lá menor natural e Dó maior usam exatamente as mesmas notas.', '{}', '{"value":true}', 'Sim. Lá menor é a relativa menor de Dó maior: as mesmas notas, mas começando em Lá.'),
  ('piano-evoluindo', 'escalas-maiores-menores', 'ex-3', 3, 'multiple_choice', 'Qual é a 7ª nota da escala de Dó maior?', '{"options":[{"id":"a","text":"Dó"},{"id":"b","text":"Lá"},{"id":"c","text":"Si"}]}', '{"correctOptionId":"c"}', 'Dó, Ré, Mi, Fá, Sol, Lá, Si: a sétima nota é Si.'),
  ('piano-evoluindo', 'escalas-maiores-menores', 'ex-4', 4, 'true_false', 'Na escala maior, os semitons ficam entre o 2º e o 3º graus e entre o 5º e o 6º graus.', '{}', '{"value":false}', 'Os semitons ficam entre o 3º e o 4º graus e entre o 7º e o 8º graus (Mi–Fá e Si–Dó, em Dó maior).'),
  ('piano-evoluindo', 'acordes-e-inversoes', 'ex-1', 1, 'multiple_choice', 'Quais notas formam o acorde de Dó maior?', '{"options":[{"id":"a","text":"Dó – Mi – Sol"},{"id":"b","text":"Dó – Fá – Lá"},{"id":"c","text":"Dó – Mi♭ – Sol"}]}', '{"correctOptionId":"a"}', 'Dó maior = fundamental (Dó), terça maior (Mi) e quinta (Sol). Com Mi♭ seria Dó menor.'),
  ('piano-evoluindo', 'acordes-e-inversoes', 'ex-2', 2, 'multiple_choice', 'Mi – Sol – Dó é qual posição do acorde de Dó maior?', '{"options":[{"id":"a","text":"Posição fundamental"},{"id":"b","text":"1ª inversão"},{"id":"c","text":"2ª inversão"}]}', '{"correctOptionId":"b"}', 'Na 1ª inversão, a terça (Mi) fica no baixo.'),
  ('piano-evoluindo', 'acordes-e-inversoes', 'ex-3', 3, 'true_false', 'Na 1ª inversão, a quinta do acorde fica como nota mais grave.', '{}', '{"value":false}', 'Na 1ª inversão, a nota mais grave é a terça (Mi, em Dó maior). A quinta no baixo é a 2ª inversão.'),
  ('piano-evoluindo', 'acordes-e-inversoes', 'ex-4', 4, 'audio_choice', 'Ouça o acorde. Ele é maior ou menor?', '{"stimulus":{"kind":"chord","notes":["D4","F4","A4"]},"options":[{"id":"a","text":"Maior"},{"id":"b","text":"Menor"}]}', '{"correctOptionId":"b"}', 'Era Ré menor (Ré – Fá – Lá). A terça menor dá o caráter menor, em geral mais sombrio.'),
  ('piano-evoluindo', 'leitura-de-partitura', 'ex-1', 1, 'multiple_choice', 'Quantas linhas e quantos espaços tem a pauta?', '{"options":[{"id":"a","text":"5 linhas e 4 espaços"},{"id":"b","text":"4 linhas e 5 espaços"},{"id":"c","text":"5 linhas e 5 espaços"}]}', '{"correctOptionId":"a"}', 'A pauta tem 5 linhas e 4 espaços.'),
  ('piano-evoluindo', 'leitura-de-partitura', 'ex-2', 2, 'multiple_choice', 'Quais são as linhas da clave de Sol, de baixo para cima?', '{"options":[{"id":"a","text":"Fá – Lá – Dó – Mi"},{"id":"b","text":"Sol – Si – Ré – Fá – Lá"},{"id":"c","text":"Mi – Sol – Si – Ré – Fá"}]}', '{"correctOptionId":"c"}', 'As linhas são Mi – Sol – Si – Ré – Fá. Fá – Lá – Dó – Mi são os espaços.'),
  ('piano-evoluindo', 'leitura-de-partitura', 'ex-3', 3, 'true_false', 'Em geral, a mão esquerda do pianista lê a clave de Fá.', '{}', '{"value":true}', 'A clave de Fá cobre as notas mais graves, normalmente tocadas pela mão esquerda.'),
  ('piano-evoluindo', 'leitura-de-partitura', 'ex-4', 4, 'multiple_choice', 'Na clave de Sol, qual nota fica na 3ª linha (contando de baixo para cima)?', '{"options":[{"id":"a","text":"Si"},{"id":"b","text":"Sol"},{"id":"c","text":"Ré"}]}', '{"correctOptionId":"a"}', 'As linhas são Mi, Sol, Si, Ré, Fá. A terceira é Si.'),
  ('piano-evoluindo', 'dinamica-e-articulacao', 'ex-1', 1, 'multiple_choice', 'O que significa a indicação f na partitura?', '{"options":[{"id":"a","text":"Forte"},{"id":"b","text":"Fraco"},{"id":"c","text":"Rápido"}]}', '{"correctOptionId":"a"}', 'f vem de forte. Para tocar fraco, a indicação é p (piano).'),
  ('piano-evoluindo', 'dinamica-e-articulacao', 'ex-2', 2, 'multiple_choice', 'Qual é a ordem correta, do mais fraco para o mais forte?', '{"options":[{"id":"a","text":"pp – p – mp – mf – f – ff"},{"id":"b","text":"p – pp – mf – mp – ff – f"},{"id":"c","text":"ff – f – mf – mp – p – pp"}]}', '{"correctOptionId":"a"}', 'A ordem crescente é pp – p – mp – mf – f – ff.'),
  ('piano-evoluindo', 'dinamica-e-articulacao', 'ex-3', 3, 'multiple_choice', 'Notas curtas e destacadas, marcadas com um ponto, são chamadas de:', '{"options":[{"id":"a","text":"Legato"},{"id":"b","text":"Fortíssimo"},{"id":"c","text":"Staccato"}]}', '{"correctOptionId":"c"}', 'Staccato é a articulação de notas curtas e destacadas.'),
  ('piano-evoluindo', 'dinamica-e-articulacao', 'ex-4', 4, 'true_false', 'No legato, há uma pausa curta entre cada nota.', '{}', '{"value":false}', 'No legato, as notas são ligadas, sem pausa entre elas.'),
  ('piano-evoluindo', 'pecas-classicas', 'ex-1', 1, 'multiple_choice', 'Qual é uma boa estratégia para aprender uma peça nova?', '{"options":[{"id":"a","text":"Tocar tudo no andamento final desde o começo"},{"id":"b","text":"Dividir em frases curtas e estudar cada mão separada"},{"id":"c","text":"Estudar só a mão direita até decorar a peça inteira"}]}', '{"correctOptionId":"b"}', 'Frases curtas, mãos separadas e andamento lento formam a base de um estudo eficiente.'),
  ('piano-evoluindo', 'pecas-classicas', 'ex-2', 2, 'true_false', 'Aumentar o andamento aos poucos ajuda a manter a regularidade.', '{}', '{"value":true}', 'Sim. Acelerar de forma gradual evita erros e mantém o pulso estável.'),
  ('piano-evoluindo', 'pecas-classicas', 'ex-3', 3, 'multiple_choice', 'Quem compôs Für Elise (Para Elisa)?', '{"options":[{"id":"a","text":"Mozart"},{"id":"b","text":"Schumann"},{"id":"c","text":"Beethoven"}]}', '{"correctOptionId":"c"}', 'Beethoven. Mozart compôs a Sonata Fácil em Dó maior, e Schumann, o Álbum para a Juventude.'),
  ('piano-evoluindo', 'pecas-classicas', 'ex-4', 4, 'multiple_choice', 'Para que serve o metrônomo no estudo de uma peça?', '{"options":[{"id":"a","text":"Afinar o piano"},{"id":"b","text":"Manter o pulso regular"},{"id":"c","text":"Aumentar o volume"}]}', '{"correctOptionId":"b"}', 'O metrônomo marca um pulso constante, ajudando a tocar com regularidade.'),
  ('piano-evoluindo', 'subir-ao-palco', 'ex-1', 1, 'multiple_choice', 'O que ajuda a lidar com o nervosismo antes de tocar?', '{"options":[{"id":"a","text":"Evitar ensaiar para não se cansar"},{"id":"b","text":"Tocar mais rápido para acabar logo"},{"id":"c","text":"Ensaiar a peça de ponta a ponta, simulando a apresentação"}]}', '{"correctOptionId":"c"}', 'Ensaiar sem parar, nas condições da apresentação, prepara o corpo e a mente.'),
  ('piano-evoluindo', 'subir-ao-palco', 'ex-2', 2, 'true_false', 'Se errar durante a apresentação, o melhor é parar e recomeçar do início.', '{}', '{"value":false}', 'O ideal é continuar tocando. Praticar a peça sem parar prepara você para isso.'),
  ('piano-evoluindo', 'subir-ao-palco', 'ex-3', 3, 'true_false', 'Sentir nervosismo antes de tocar é normal, mesmo entre profissionais.', '{}', '{"value":true}', 'Sim. O nervosismo é comum; o que importa é se preparar para conviver com ele.'),
  ('teoria-harmonia-escalas', 'tonalidades-e-armaduras', 'ex-1', 1, 'multiple_choice', 'Quantos sustenidos tem a armadura de Sol maior?', '{"options":[{"id":"a","text":"Nenhum"},{"id":"b","text":"1 (Fá#)"},{"id":"c","text":"2 (Fá# e Dó#)"}]}', '{"correctOptionId":"b"}', 'Sol maior tem 1 sustenido: Fá#.'),
  ('teoria-harmonia-escalas', 'tonalidades-e-armaduras', 'ex-2', 2, 'multiple_choice', 'Qual tonalidade tem 2 sustenidos (Fá# e Dó#)?', '{"options":[{"id":"a","text":"Sol maior"},{"id":"b","text":"Lá maior"},{"id":"c","text":"Ré maior"}]}', '{"correctOptionId":"c"}', 'Ré maior tem 2 sustenidos: Fá# e Dó#. Sol maior tem 1, e Lá maior tem 3.'),
  ('teoria-harmonia-escalas', 'tonalidades-e-armaduras', 'ex-3', 3, 'true_false', 'Dó maior não tem nenhum sustenido nem bemol na armadura.', '{}', '{"value":true}', 'Sim. Dó maior usa só as teclas brancas, sem alterações.'),
  ('teoria-harmonia-escalas', 'tonalidades-e-armaduras', 'ex-4', 4, 'multiple_choice', 'Onde fica escrita a armadura de clave?', '{"options":[{"id":"a","text":"No início da pauta, logo depois da clave"},{"id":"b","text":"No fim da música"},{"id":"c","text":"Só sobre as notas alteradas"}]}', '{"correctOptionId":"a"}', 'A armadura fica no início da pauta, logo depois da clave, e vale para a música inteira.'),
  ('teoria-harmonia-escalas', 'escalas-menores', 'ex-1', 1, 'multiple_choice', 'Qual forma da escala menor usa as mesmas notas da relativa maior, sem alterações?', '{"options":[{"id":"a","text":"Harmônica"},{"id":"b","text":"Melódica"},{"id":"c","text":"Natural"}]}', '{"correctOptionId":"c"}', 'A menor natural usa as mesmas notas da relativa maior. Lá menor natural e Dó maior, por exemplo.'),
  ('teoria-harmonia-escalas', 'escalas-menores', 'ex-2', 2, 'multiple_choice', 'Qual é a escala de Lá menor harmônica?', '{"options":[{"id":"a","text":"Lá, Si, Dó, Ré, Mi, Fá, Sol#"},{"id":"b","text":"Lá, Si, Dó, Ré, Mi, Fá, Sol"},{"id":"c","text":"Lá, Si, Dó#, Ré, Mi, Fá#, Sol#"}]}', '{"correctOptionId":"a"}', 'A harmônica é a natural com o 7º grau elevado: Sol vira Sol#. A segunda opção é a natural; a terceira é Lá maior.'),
  ('teoria-harmonia-escalas', 'escalas-menores', 'ex-3', 3, 'true_false', 'Na escala menor harmônica, o 7º grau é elevado em um semitom.', '{}', '{"value":true}', 'Sim. É isso que cria o salto de um tom e meio entre o 6º e o 7º graus.'),
  ('teoria-harmonia-escalas', 'escalas-menores', 'ex-4', 4, 'true_false', 'Na escala menor melódica (subindo), apenas o 7º grau é elevado.', '{}', '{"value":false}', 'Subindo, a menor melódica eleva o 6º e o 7º graus.'),
  ('teoria-harmonia-escalas', 'intervalos-e-inversoes', 'ex-1', 1, 'multiple_choice', 'Qual é o intervalo entre Dó e Sol?', '{"options":[{"id":"a","text":"3ª maior"},{"id":"b","text":"4ª justa"},{"id":"c","text":"5ª justa"}]}', '{"correctOptionId":"c"}', 'De Dó a Sol, contando as duas pontas: Dó, Ré, Mi, Fá, Sol = 5 notas. É uma 5ª justa.'),
  ('teoria-harmonia-escalas', 'intervalos-e-inversoes', 'ex-2', 2, 'multiple_choice', 'Ao inverter uma 3ª, obtemos uma:', '{"options":[{"id":"a","text":"4ª"},{"id":"b","text":"6ª"},{"id":"c","text":"7ª"}]}', '{"correctOptionId":"b"}', 'O número do intervalo e o do invertido somam 9: 3 + 6 = 9.'),
  ('teoria-harmonia-escalas', 'intervalos-e-inversoes', 'ex-3', 3, 'true_false', 'Ao inverter uma 5ª justa, obtém-se uma 4ª justa.', '{}', '{"value":true}', 'Sim. 5 + 4 = 9, e o intervalo justo continua justo.'),
  ('teoria-harmonia-escalas', 'intervalos-e-inversoes', 'ex-4', 4, 'audio_choice', 'Ouça as duas notas tocadas juntas. A terça é maior ou menor?', '{"stimulus":{"kind":"chord","notes":["E4","G4"]},"options":[{"id":"a","text":"3ª maior"},{"id":"b","text":"3ª menor"}]}', '{"correctOptionId":"b"}', 'De Mi a Sol são 3 semitons: uma 3ª menor, de som mais fechado. Mi–Sol# seria uma 3ª maior.'),
  ('teoria-harmonia-escalas', 'campo-harmonico', 'ex-1', 1, 'multiple_choice', 'Quais são os acordes do campo harmônico de Dó maior, em ordem?', '{"options":[{"id":"a","text":"C – D – E – F – G – A – B"},{"id":"b","text":"C – Dm – Em – F – G – A – Bdim"},{"id":"c","text":"C – Dm – Em – F – G – Am – Bdim"}]}', '{"correctOptionId":"c"}', 'O campo harmônico de Dó maior é C – Dm – Em – F – G – Am – Bdim.'),
  ('teoria-harmonia-escalas', 'campo-harmonico', 'ex-2', 2, 'multiple_choice', 'Qual grau do campo harmônico de Dó maior é o acorde G?', '{"options":[{"id":"a","text":"IV"},{"id":"b","text":"V"},{"id":"c","text":"vi"}]}', '{"correctOptionId":"b"}', 'Dó (I), Ré (II), Mi (III), Fá (IV), Sol (V): G é o V grau, a dominante.'),
  ('teoria-harmonia-escalas', 'campo-harmonico', 'ex-3', 3, 'true_false', 'No campo harmônico maior, o acorde do grau vii é um acorde maior.', '{}', '{"value":false}', 'O grau vii forma um acorde diminuto (Bdim, em Dó maior).'),
  ('teoria-harmonia-escalas', 'campo-harmonico', 'ex-4', 4, 'multiple_choice', 'Em Sol maior, qual é o acorde do grau IV?', '{"options":[{"id":"a","text":"C"},{"id":"b","text":"D"},{"id":"c","text":"Em"}]}', '{"correctOptionId":"a"}', 'Sol (I), Lá (II), Si (III), Dó (IV): o acorde do IV grau é C.'),
  ('teoria-harmonia-escalas', 'cadencias', 'ex-1', 1, 'multiple_choice', 'Qual sequência forma a cadência autêntica em Dó maior?', '{"options":[{"id":"a","text":"F → C"},{"id":"b","text":"C → Am"},{"id":"c","text":"G → C"}]}', '{"correctOptionId":"c"}', 'A cadência autêntica é V → I (G → C). F → C é a cadência plagal.'),
  ('teoria-harmonia-escalas', 'cadencias', 'ex-2', 2, 'multiple_choice', 'A cadência plagal (IV → I) é conhecida como:', '{"options":[{"id":"a","text":"Semicadência"},{"id":"b","text":"O ''amém'' dos hinos"},{"id":"c","text":"Cadência de engano"}]}', '{"correctOptionId":"b"}', 'A cadência plagal (como F → C) é conhecida como o ''amém'' dos hinos.'),
  ('teoria-harmonia-escalas', 'cadencias', 'ex-3', 3, 'true_false', 'A semicadência termina no acorde V, deixando a frase em suspenso.', '{}', '{"value":true}', 'Sim. Terminar no V dá a sensação de vírgula, de que a música ainda vai continuar.'),
  ('teoria-harmonia-escalas', 'cadencias', 'ex-4', 4, 'multiple_choice', 'Em Dó maior, G → Am é um exemplo de qual cadência?', '{"options":[{"id":"a","text":"De engano"},{"id":"b","text":"Autêntica"},{"id":"c","text":"Plagal"}]}', '{"correctOptionId":"a"}', 'Esperamos o I (C), mas a música vai para o vi (Am): é a cadência de engano.')
) AS v(track_slug, lesson_slug, key, position, type, prompt, payload, solution, explanation)
JOIN tracks t ON t.slug = v.track_slug
JOIN stages s ON s.track_id = t.id
JOIN lessons l ON l.stage_id = s.id AND l.slug = v.lesson_slug
ON CONFLICT (lesson_id, key) DO UPDATE
  SET type = EXCLUDED.type, prompt = EXCLUDED.prompt, payload = EXCLUDED.payload,
      solution = EXCLUDED.solution, explanation = EXCLUDED.explanation;

COMMIT;

-- Conferência: as colunas "licoes" e "esperado" devem ser iguais
SELECT t.slug AS trilha, t.total_lessons AS esperado,
       count(DISTINCT l.id) AS licoes, count(e.id) AS exercicios
FROM tracks t
LEFT JOIN stages s ON s.track_id = t.id
LEFT JOIN lessons l ON l.stage_id = s.id
LEFT JOIN exercises e ON e.lesson_id = l.id
WHERE t.slug IN ('piano-evoluindo', 'teoria-harmonia-escalas')
GROUP BY t.slug, t.total_lessons
ORDER BY t.slug;
